ControlPropertyState.AutoRuleBindingString:
// 1. Avisamos al usuario para que espere un segundo
Notify("Generando sesiones, por favor espera...", NotificationType.Information);

// 2. Disparamos la creación masiva directamente en SharePoint
ForAll(
    Sequence(Value(dd_Curs_Area_3.Selected.Value)), 

    Patch(
        'Sesiones Formación',
        Defaults('Sesiones Formación'), // 👈 Esto le dice a SharePoint: "Crea una fila NUEVA"
        {
            // ⚠️ CRUCIAL: Enlazamos la sesión al curso para que tu galería la pueda ver
            ID_Curso: varFormItemSelected.ID, 

            Fecha: If(
                dd_Curs_Denom_3.Selected.Value = "Única", DatePicker1.SelectedDate,
                dd_Curs_Denom_3.Selected.Value = "Semanal", DateAdd(DatePicker1.SelectedDate, (Value - 1) * 7, TimeUnit.Days),
                dd_Curs_Denom_3.Selected.Value = "Quincenal", DateAdd(DatePicker1.SelectedDate, (Value - 1) * 14, TimeUnit.Days),
                dd_Curs_Denom_3.Selected.Value = "Mensual", DateAdd(DatePicker1.SelectedDate, Value - 1, TimeUnit.Months)
            ),
            // Le damos un nombre base para que no quede totalmente en blanco (ej: "Sesión 1")
            Nombre: "Sesión " & Value, 
            Objetivos: "",
            Horas: Value(dd_Curs_Area_4.Selected.Value), // Uso Value() asumiendo que Horas es tipo número en SP
            Contenidos: ""
        }
    )
);

// 3. Forzamos a la app a mirar a SharePoint para actualizar la galería al instante
Refresh('Sesiones Formación');

// 4. Confirmamos el éxito
Notify("✅ ¡Sesiones generadas y guardadas correctamente!", NotificationType.Success)
